/* @name InternalUsersSetUserDeactivated */
/* AUTO-GENERATED FROM SOURCE .sql. DO NOT EDIT THIS FILE. */
WITH deactivated AS (
  UPDATE
    internal.users
  SET
    deactivated_at = NOW()
  WHERE
    id = :userId!
    AND status = 'ACTIVE'
  RETURNING
    id
    , status
)
UPDATE
  internal.users_authentication AS a
SET
  password_hash = :newPasswordHash!
  , refresh_token_hash = NULL
FROM
  deactivated AS d
WHERE
  a.user_id = d.id
RETURNING
  a.user_id
  , d.status
;
